mapper.select:
SELECT a.* FROM contact_friend_task_account a LEFT JOIN (SELECT r.tenant_id, r.task_account_id, FROM contact_friend_task_recipient r WHERE r.task_id = #{query.taskId} GROUP BY r.tenant_id, r.task_account_id) m ON m.tenant_id = a.tenant_id AND m.task_account_id = a.id WHERE a.task_id = #{query.taskId} ORDER BY
COALESCE(m.planned_num,0) COALESCE(m.confirmed_num,0) COALESCE(m.failed_num,0) COALESCE(m.processed_num,0) COALESCE(m.delivered_num,0) COALESCE(m.read_num,0) COALESCE(m.unknown_num,0) COALESCE(m.skipped_num,0) a.id
ASCDESC, a.id ASC LIMIT #{query.limit} OFFSET #{query.offset}

mapper.sql:
r.task_id = #{taskId}
AND r.task_account_id = #{query.taskAccountId}
AND r.send_status = #{query.sendStatus}
AND COALESCE(r.error_code,'UNSPECIFIED') = #{query.errorCode}

  AND (r.send_status = 'SUCCESS' OR r.delivered_at IS NOT NULL OR r.read_at IS NOT NULL)
  AND r.send_status = 'SUCCESS' AND r.delivered_at IS NULL AND r.read_at IS NULL
  AND (r.delivered_at IS NOT NULL OR r.read_at IS NOT NULL)
  AND r.delivered_at IS NOT NULL AND r.read_at IS NULL
  AND r.read_at IS NOT NULL
